fun longestCommonSubsequence(a: String, b: String): Int {
    // dp[i][j] = LCS of a.take(i) and b.take(j)
    val dp = Array(a.length + 1) { IntArray(b.length + 1) }

    for (i in 1..a.length) {
        for (j in 1..b.length) {
            dp[i][j] = if (a[i - 1] == b[j - 1]) {
                dp[i - 1][j - 1] + 1                       // match: extend the diagonal
            } else {
                maxOf(dp[i - 1][j], dp[i][j - 1])          // drop one char from either
            }
        }
    }
    return dp[a.length][b.length]
}

fun minDistance(a: String, b: String): Int {
    val dp = Array(a.length + 1) { IntArray(b.length + 1) }

    for (i in 0..a.length) dp[i][0] = i        // delete every char of a
    for (j in 0..b.length) dp[0][j] = j        // insert every char of b

    for (i in 1..a.length) {
        for (j in 1..b.length) {
            dp[i][j] = if (a[i - 1] == b[j - 1]) {
                dp[i - 1][j - 1]                            // free — no operation needed
            } else {
                1 + minOf(
                    dp[i - 1][j - 1],   // replace
                    dp[i - 1][j],       // delete from a
                    dp[i][j - 1],       // insert into a
                )
            }
        }
    }
    return dp[a.length][b.length]
}

