import java.util.PriorityQueue

fun merge(intervals: Array<IntArray>): Array<IntArray> {
    if (intervals.isEmpty()) return emptyArray()
    intervals.sortBy { it[0] }

    val result = mutableListOf(intervals[0])
    for (i in 1 until intervals.size) {
        val last = result.last()
        val current = intervals[i]
        if (current[0] <= last[1]) {
            last[1] = maxOf(last[1], current[1])   // overlap: extend
        } else {
            result.add(current)                     // disjoint: start a new one
        }
    }
    return result.toTypedArray()
}

fun minMeetingRooms(intervals: Array<IntArray>): Int {
    if (intervals.isEmpty()) return 0
    intervals.sortBy { it[0] }

    // Min-heap of end times: the top is the room that frees up soonest
    val endTimes = PriorityQueue<Int>()

    for (meeting in intervals) {
        // If the earliest-ending room is already free, reuse it
        if (endTimes.isNotEmpty() && endTimes.peek() <= meeting[0]) {
            endTimes.poll()
        }
        endTimes.offer(meeting[1])
    }
    return endTimes.size          // rooms still held == peak concurrency
}

