class Trie {
    private class Node {
        val children = HashMap<Char, Node>()
        var isWord = false
        var frequency = 0
    }

    private val root = Node()

    fun insert(word: String, frequency: Int = 1) {
        var node = root
        for (c in word) node = node.children.getOrPut(c) { Node() }
        node.isWord = true
        node.frequency += frequency
    }

    private fun walk(prefix: String): Node? {
        var node = root
        for (c in prefix) node = node.children[c] ?: return null
        return node
    }

    fun search(word: String): Boolean = walk(word)?.isWord == true

    fun startsWith(prefix: String): Boolean = walk(prefix) != null

    fun suggest(prefix: String, limit: Int = 10): List<String> {
        val start = walk(prefix) ?: return emptyList()
        val found = mutableListOf<Pair<String, Int>>()

        fun dfs(node: Node, built: StringBuilder) {
            if (found.size >= limit * 4) return          // bound the search
            if (node.isWord) found.add(built.toString() to node.frequency)
            for ((c, child) in node.children) {
                built.append(c)
                dfs(child, built)
                built.deleteCharAt(built.lastIndex)      // backtrack
            }
        }
        dfs(start, StringBuilder(prefix))

        return found.sortedByDescending { it.second }.take(limit).map { it.first }
    }
}

