class SingleFlightCache<K, V>(
    private val scope: CoroutineScope,
    private val fetcher: suspend (K) -> V,
) {
    private val mutex = Mutex()
    private val cache = HashMap<K, V>()
    private val inFlight = HashMap<K, Deferred<V>>()

    suspend fun get(key: K): V {
        // Fast path — already cached
        mutex.withLock { cache[key] }?.let { return it }

        val deferred = mutex.withLock {
            // Re-check inside the lock: another coroutine may have finished while we waited
            cache[key]?.let { return it }

            inFlight[key] ?: scope.async {
                fetcher(key)
            }.also { inFlight[key] = it }
        }

        return try {
            val value = deferred.await()          // awaited OUTSIDE the lock
            mutex.withLock {
                cache[key] = value
                inFlight.remove(key)
            }
            value
        } catch (e: Throwable) {
            // A failure must not be cached, or every future caller inherits it
            mutex.withLock { inFlight.remove(key) }
            throw e
        }
    }

    suspend fun invalidate(key: K) = mutex.withLock { cache.remove(key) }
}

