@Entity(tableName = "mutations")
data class MutationEntity(
    @PrimaryKey val id: String,          // client-generated UUID == idempotency key
    val type: String,                     // CREATE_NOTE, LIKE_POST, ...
    val payload: String,                  // serialized body
    val createdAt: Long,                  // preserves ordering
    val attempts: Int = 0,
    val status: String = "PENDING",      // PENDING | FAILED | DONE
)

class OutboxWorker(
    ctx: Context,
    params: WorkerParameters,
    private val dao: MutationDao,
    private val api: Api,
) : CoroutineWorker(ctx, params) {

    override suspend fun doWork(): Result {
        // FIFO by creation time — ordering is a property of the query, not of memory
        val pending = dao.pending(limit = 50)

        for (mutation in pending) {
            try {
                // The server dedupes on this key, so a lost response cannot duplicate
                api.submit(mutation.toRequest(), idempotencyKey = mutation.id)
                dao.markDone(mutation.id)
            } catch (e: IOException) {
                // Transient: stop here so strict ordering is preserved, and retry the batch
                dao.incrementAttempts(mutation.id)
                return if (mutation.attempts + 1 >= MAX_ATTEMPTS) {
                    dao.markFailed(mutation.id)   // surface to the user, unblock the queue
                    Result.retry()
                } else {
                    Result.retry()                 // WorkManager applies the backoff
                }
            } catch (e: HttpException) {
                // 4xx is permanent — retrying forever would wedge the queue
                if (e.code() in 400..499) dao.markFailed(mutation.id) else return Result.retry()
            }
        }
        return Result.success()
    }

    companion object { const val MAX_ATTEMPTS = 5 }
}

// Enqueue: unique work so a burst of edits doesn't spawn a worker per edit
fun schedule(wm: WorkManager) = wm.enqueueUniqueWork(
    "outbox",
    ExistingWorkPolicy.KEEP,
    OneTimeWorkRequestBuilder<OutboxWorker>()
        .setConstraints(Constraints.Builder().setRequiredNetworkType(NetworkType.CONNECTED).build())
        .setBackoffCriteria(BackoffPolicy.EXPONENTIAL, 30, TimeUnit.SECONDS)
        .build()
)

